def _ledger(data, revision_first, discounted):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_first:
            key = (event.get("revision", 0), pos)
        else:
            key = (seq, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    constraints = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
    best_vector = None
    best = None

    def cycle(assignments):
        state = {}
        def visit(name):
            if state.get(name) == 1:
                return True
            if state.get(name) == 2:
                return False
            state[name] = 1
            row = assignments[name]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                if visit(dep["name"]):
                    return True
            state[name] = 2
            return False
        return any(visit(name) for name in assignments if not state.get(name))

    def search(assignments, limits):
        nonlocal best_vector, best
        for name, row in assignments.items():
            for low, high in limits.get(name, []):
                if not low <= row["version"] <= high:
                    return
        pending = [name for name in limits if name not in assignments]
        if not pending:
            if cycle(assignments):
                return
            vector = tuple(assignments[n]["version"] if n in assignments else -1 for n in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {n: row["version"] for n, row in assignments.items()}
            return

        name = pending[0]
        ranges = limits[name]
        low = max(r[0] for r in ranges)
        high = min(r[1] for r in ranges)
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            next_assignments = dict(assignments)
            next_assignments[name] = row
            next_limits = {n: list(rs) for n, rs in limits.items()}
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                interval = (dep["min"], dep["max"])
                if dep_name in next_assignments:
                    version = next_assignments[dep_name]["version"]
                    if not interval[0] <= version <= interval[1]:
                        valid = False
                        break
                next_limits.setdefault(dep_name, []).append(interval)
            if valid:
                search(next_assignments, next_limits)

    search({}, constraints)
    return {"error": "unsatisfiable"} if best is None else {"versions": best}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    n = len(jobs)

    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = tuple(sorted(job["id"] for job in selected))
        if any(i in blocked for i in ids) or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(counts.get(group, 0) > k for group in counts):
            continue
        events = sorted((job["start"], 1) for job in selected) + sorted((job["end"], -1) for job in selected)
        # At a shared endpoint, ends precede starts (half-open intervals).
        events.sort(key=lambda item: (item[0], item[1]))
        active = 0
        valid = True
        for _, delta in events:
            active += delta
            if active > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in selected)
        if best_value is None or value > best_value or (value == best_value and ids > best_ids):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    import heapq
    required = data.get("required", [])
    indexes = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = 0
    if data["source"] in indexes:
        initial_mask |= 1 << indexes[data["source"]]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                time = depart + duration
                if time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask
                if next_node in indexes:
                    next_mask |= 1 << indexes[next_node]
                next_state = (next_node, next_mask, left)
                if time < distances.get(next_state, float("inf")):
                    distances[next_state] = time
                    heapq.heappush(queue, (time,) + next_state)
    return {"arrival": None}


